/* Speculative Score-Draft Starter */

// The core of this track is a single, relentless MonoSynth.
const motorikBass = new Tone.MonoSynth({
  oscillator: {
    type: 'fatsawtooth',
    count: 4,
    spread: 20
  },
  envelope: {
    attack: 0.01,
    decay: 0.2,
    sustain: 0.1,
    release: 0.2
  },
  filterEnvelope: {
    attack: 0.01,
    decay: 0.1,
    sustain: 0.5,
    release: 0.8,
    baseFrequency: 200,
    octaves: 2.5
  }
}).toDestination();

// Add some grit and connect to a light reverb.
const drive = new Tone.Distortion(0.4).connect(motorikBass);

// The pattern is a 2-bar sequence of 8th notes in E minor.
const pattern = new Tone.Sequence((time, note) => {
  motorikBass.triggerAttackRelease(note, '8n', time);
}, [
  'E2', 'G2', 'A2', 'G2', 'E2', 'B1', 'D2', 'E2',
  'E2', 'G2', 'A2', 'G2', 'A2', 'G2', 'B1', 'E2'
], '8n');

// Set tempo and start the transport.
Tone.Transport.bpm.value = 120;
